type Funnel = { viewed: number; carted: number; purchased: number };
const rate = (part: number, whole: number) => whole === 0 ? 0 : part / whole;
export function analyze(funnel: Funnel) {
  return {
    viewToCart: rate(funnel.carted, funnel.viewed),
    cartToPurchase: rate(funnel.purchased, funnel.carted),
  };
}
console.log(analyze({ viewed: 1000, carted: 120, purchased: 30 }));

exercise.solution:
For Read a funnel without inventing causality, the solution keeps one authority and specifically applies “define population, window, unit, and event order, show volumes beside rates, and segment only with sufficient sample”. It makes views count sessions while purchases count orders from another period, producing a meaningless rate reproducible and then controlled, and is accepted only when viewToCart is 0.12, cartToPurchase is 0.25, a zero denominator yields zero, and each stage documents unit and period.
